"""Tests for tasks_api.models (Tag, Task, TaskStatus, TaskPriority)."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_is_str_enum(self):
        assert isinstance(TaskStatus.PENDING, str)


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_first(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)


class TestTag:
    @pytest.mark.parametrize("raw,expected", [
        ("python", "python"),
        ("  Python  ", "python"),
        ("UPPER", "upper"),
        ("a-b_c", "a-b_c"),
        ("123", "123"),
    ])
    def test_normalization(self, raw, expected):
        assert Tag(raw).name == expected

    def test_empty_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_exactly_32_chars(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    def test_illegal_char_raises(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")

    @pytest.mark.parametrize("bad", ["a@b", "a.b", "a/b", "a!b"])
    def test_various_illegal_chars(self, bad):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(bad)

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore


class TestTask:
    def test_default_fields(self):
        task = Task(id=1, title="Test")
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.due_at is None
        assert task.completed_at is None
        assert task.tags == []
        assert task.created_at is not None

    def test_is_overdue_no_due_at(self):
        task = Task(id=1, title="Test")
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

    def test_is_overdue_done_task(self):
        past = datetime(2024, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="Test", status=TaskStatus.DONE, due_at=past)
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

    def test_is_overdue_past_due(self):
        past = datetime(2024, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="Test", due_at=past)
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is True

    def test_is_overdue_future_due(self):
        future = datetime(2030, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="Test", due_at=future)
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False

"""Tests for tasks_api.queries (TaskQuery, apply_query, TaskPage)."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query


NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _make_task(id, title="Task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
               due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, tags=tags or [],
        created_at=created_at or datetime(2025, 1, id, tzinfo=timezone.utc),
    )


class TestTaskQuery:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalization(self):
        q = TaskQuery(tag="  Python  ")
        assert q.tag == "python"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_make_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_make_task(1)], total=1, limit=20, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact(self):
        tasks = [_make_task(1), _make_task(2)]
        page = TaskPage(items=tasks, total=2, limit=2, offset=0)
        assert page.has_more is False


class TestApplyQuery:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Buy milk", status=TaskStatus.PENDING, priority=TaskPriority.LOW,
                       tags=[Tag("shopping")]),
            _make_task(2, "Write report", status=TaskStatus.DONE, priority=TaskPriority.HIGH,
                       tags=[Tag("work")]),
            _make_task(3, "Call dentist", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
                       due_at=datetime(2024, 1, 1, tzinfo=timezone.utc)),  # overdue
            _make_task(4, "Buy groceries", status=TaskStatus.PENDING, priority=TaskPriority.HIGH,
                       tags=[Tag("shopping")]),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4
        assert len(page.items) == 4

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BUY"), NOW)
        assert page.total == 2

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        assert page.total == 3
        assert 3 not in [t.id for t in page.items]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        keys = [TaskPriority.order_key(p) for p in priorities]
        assert keys == sorted(keys)

    def test_sort_descending(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower, reverse=True)

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Task 3 has due_at set, others are None — task 3 should be first
        assert page.items[0].id == 3

    def test_pagination_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 4
        assert page.has_more is True

    def test_pagination_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=2), NOW)
        assert len(page.items) == 2
        assert page.offset == 2
        assert page.has_more is False

    def test_pagination_offset_beyond(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 4
        assert page.has_more is False

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="shopping"), NOW)
        assert page.total == 2
        assert all(t.status == TaskStatus.PENDING for t in page.items)

"""Tests for tasks_api.repository (InMemoryTaskRepository, normalize_tags)."""

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, id=1, title="Test"):
        return Task(id=id, title=title)

    def test_add_and_get(self, repo):
        task = self._make_task()
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task(1))

    def test_list_returns_all(self, repo):
        repo.add(self._make_task(1))
        repo.add(self._make_task(2, "Second"))
        result = list(repo.list())
        assert len(result) == 2

    def test_list_returns_snapshot(self, repo):
        repo.add(self._make_task(1))
        first = list(repo.list())
        repo.add(self._make_task(2, "Another"))
        second = list(repo.list())
        assert len(first) == 1
        assert len(second) == 2

    def test_update_existing(self, repo):
        task = self._make_task(1)
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(99))

    def test_delete_existing(self, repo):
        repo.add(self._make_task(1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(99) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_string_inputs(self):
        result = normalize_tags(["Python", "flask"])
        assert [t.name for t in result] == ["python", "flask"]

    def test_tag_inputs(self):
        result = normalize_tags([Tag("hello"), Tag("WORLD")])
        assert [t.name for t in result] == ["hello", "world"]

    def test_deduplication(self):
        result = normalize_tags(["Python", "python", "PYTHON"])
        assert len(result) == 1
        assert result[0].name == "python"

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["beta", "alpha", "beta"])
        assert [t.name for t in result] == ["beta", "alpha"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_mixed_tag_and_str(self):
        result = normalize_tags([Tag("one"), "TWO", Tag("one")])
        assert [t.name for t in result] == ["one", "two"]

