class TestApplyQuery:
    @pytest.fixture
    def tasks(self):
        return [
            _make_task(1, "Buy milk", status=TaskStatus.PENDING, priority=TaskPriority.LOW,
                       tags=[Tag("shopping")]),
            _make_task(2, "Write report", status=TaskStatus.DONE, priority=TaskPriority.HIGH,
                       tags=[Tag("work")]),
            _make_task(3, "Call dentist", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
                       due_at=datetime(2024, 1, 1, tzinfo=timezone.utc)),  # overdue
            _make_task(4, "Buy groceries", status=TaskStatus.PENDING, priority=TaskPriority.HIGH,
                       tags=[Tag("shopping")]),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4
        assert len(page.items) == 4

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="BUY"), NOW)
        assert page.total == 2

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        assert page.total == 3
        assert 3 not in [t.id for t in page.items]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower)

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        keys = [TaskPriority.order_key(p) for p in priorities]
        assert keys == sorted(keys)

    def test_sort_descending(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        titles = [t.title for t in page.items]
        assert titles == sorted(titles, key=str.lower, reverse=True)

    def test_sort_by_due_at_none_last(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Task 3 has due_at set, others are None — task 3 should be first
        assert page.items[0].id == 3

    def test_pagination_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 4
        assert page.has_more is True

    def test_pagination_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=2), NOW)
        assert len(page.items) == 2
        assert page.offset == 2
        assert page.has_more is False

    def test_pagination_offset_beyond(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 4
        assert page.has_more is False

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="shopping"), NOW)
        assert page.total == 2
        assert all(t.status == TaskStatus.PENDING for t in page.items)

